// ЗГЕНЕРОВАНО `deno task client:assets` з client/styles/theme.css — не редагувати.
//
// Тема доїжджає до застосунку модулем, а не файлом: чому саме так — у
// tools/generate-client-assets.ts.

export const THEME_CSS: string = "/* Тема фреймворку та контракти компонентів ui-kit.\n *\n * Це ЧИСТИЙ CSS — тут навмисно немає ні `@import \"tailwindcss\"`, ні `@source`,\n * ні `@plugin \"daisyui\"`, ні імпортів з npm. Причина: файл їде у складі пакета\n * `client`, а збірка Tailwind належить застосунку. Директиви тут означали б, що\n * бібліотека компілює стилі за застосунок і сканує його каталоги — раніше саме\n * так і було (`@source \"../../app\"` усередині `client/`), і це був вихід за межі\n * пакета, якого `check:deps` не бачить: він обходить лише `.ts`.\n *\n * Підключає цей файл вхід збірки застосунку — `app/styles/tailwind.css`, останнім\n * рядком, тобто ПІСЛЯ Tailwind і daisyUI. Порядок обов'язковий: правила нижче\n * написані поза `@layer` і мусять перебивати шар utilities.\n *\n * Шрифт задається змінною `--default-font-family`, а самі файли шрифту підключає\n * застосунок: `@fontsource/*` резолвиться через node_modules, яких у пакета немає.\n */\n\n/* ── 1С тема (гамма перенесена з altera_danet) ─────────── */\n[data-theme=\"1c\"],\n:root,\n:host {\n  /* DaisyUI цвета — холодні сіро-блакитні тони altera_danet */\n  --color-primary:          #2f5f8f;\n  --color-primary-content:  #ffffff;\n  --color-secondary:        #4a7ab5;\n  --color-secondary-content:#ffffff;\n  --color-accent:           #2f5f8f;\n  --color-accent-content:   #ffffff;\n  --color-neutral:          #617482;\n  --color-neutral-content:  #ffffff;\n  --color-base-100:         #ffffff;\n  --color-base-200:         #dfe5ea;\n  --color-base-300:         #b8c3cc;\n  --color-base-content:     #243746;\n  --color-info:             #2f5f8f;\n  --color-info-content:     #ffffff;\n  /* Значення підібрані під поріг AA (4.5:1), а не на око. Було: success давав\n     білому тексту 4.30, error — 3.76 і як текст, і як заливка. Зсув мінімальний\n     (гама та сама), але бейдж «Проведено» і текст помилки поля перестають бути\n     на межі читабельності. */\n  --color-success:          #28794d;   /* білий текст: 5.34 */\n  --color-warning:          #f59e0b;\n  --color-error:            #dc2626;   /* і текст на білому, і білий на заливці: 4.83 */\n  /* `-content` для цих трьох НЕ були оголошені, і це та сама пастка, що з\n     `--border` і чекбоксами: daisyUI підставляє їх без фолбеків, тож невизначена\n     змінна анулює декларацію кольору тексту, і він лишався успадкованим —\n     випадково, а не за задумом. Для warning це видно найкраще: білий на\n     помаранчевому дає 2.15, а base-content — 5.72, тож контентом мусить бути\n     саме темний. */\n  --color-success-content:  #ffffff;\n  --color-warning-content:  #243746;\n  --color-error-content:    #ffffff;\n\n  /* Семантичні токени altera_danet — для майбутніх компонентів */\n  --app-bg:             #dfe5ea;\n  --app-surface:        #f6f8fa;\n  --app-surface-strong: #ffffff;\n  --app-header:         #e7edf2;\n  --app-border:         #b8c3cc;\n  --app-border-strong:  #98a7b4;\n  /* Рамка поля вводу — окремий токен від --app-border, і темніший за нього.\n     Причина: за WCAG 1.4.11 межа контрола мусить давати 3:1 до фону, а\n     #b8c3cc на білому дає 1.79 — при плоскій темі, висоті 24px і білій заливці\n     поле переставало читатися як поле. Розділові лінії (таблиця, тулбар)\n     лишаються світлими: до них ця вимога не застосовується. */\n  --app-border-field:   #7f8f9e;       /* на білому: 3.32 */\n  --app-text:           #243746;\n  /* Приглушений текст. Було #617482 (4.85 на білому) — проходило, але не на\n     рядку під курсором (#dcebf8): там виходило 3.99. Це значення проходить на\n     всіх трьох фонах списку — білому, зебрі й підсвітці. */\n  --app-text-muted:     #5a6b7d;       /* білий 5.48 · зебра 5.33 · hover 4.51 */\n  --app-accent:         #2f5f8f;\n  --app-accent-soft:    #dfe8f1;\n\n  /* Радиусы — плоский стиль как в 1С (не частина гами) */\n  --radius-field:   2px;\n  --radius-box:     2px;\n  --radius-btn:     2px;\n  --radius-badge:   2px;\n\n  /* Структурні змінні daisyUI. Плагін підключено з `themes: false` (тема — цей\n     файл), а компоненти daisyUI (checkbox, radio, toggle, select…) спираються\n     на ці змінні БЕЗ фолбеків: невизначений `--border` анулює всю декларацію\n     рамки, і разом з `appearance: none` контрол стає невидимим — саме так\n     зникали чекбокси. Значення — під плоский стиль 1С: без глибини й шуму. */\n  --border:          1px;\n  --size-selector:   0.25rem;\n  --size-field:      0.25rem;\n  --radius-selector: 2px;\n  --depth:           0;\n  --noise:           0;\n\n  /* Шрифт */\n  --default-font-family: \"Roboto\", sans-serif;\n  --default-font-size:   0.875rem;\n\n  /* Розмір гліфа інтерфейсу — ОДИН важіль на всі іконки в контролах.\n     Іконки малюються інлайновим `<svg>` у двох десятках файлів, і кожен колись\n     писав свій розмір атрибутами (12, 13, 14) — тому «зробити іконки більшими»\n     не виходило: правка одного місця нічого не міняла, а знайти решту було ніде.\n     Тепер розмір задає тема (`.btn > svg`, `.input > svg` нижче), а атрибути\n     лишаються значенням за замовчуванням для гліфа ПОЗА контролом.\n     У px, а не rem: `html` тут має font-size 0.875rem, тож `1rem` — це 14px, і\n     число читалося б не тим, чим виглядає. 16px — розмір `.loading`, тобто\n     кнопка не смикається, коли іконка на час запиту міняється на спіннер. */\n  --icon-size: 16px;\n}\n\n/* ── Глобальный сброс ────────────────────────────────── */\n*, *::before, *::after { box-sizing: border-box; }\n\nhtml, body {\n  font-size: var(--default-font-size);\n  background: var(--color-base-200);\n  color: var(--color-base-content);\n  font-family: var(--default-font-family);\n}\n\n/* ── Компактность компонентов ────────────────────────── */\n\n/* Кнопки — плоские, компактные */\n.btn {\n  font-size: var(--default-font-size);\n  height: 24px;\n  min-height: 24px;\n  padding-inline: 10px;\n  border-radius: var(--radius-btn);\n  font-weight: 400;\n  border: 1px solid var(--app-border);\n  background: #f5f7fa;\n  color: var(--app-text);\n}\n.btn:hover { background: #e3eaf3; }\n.btn-primary {\n  background: var(--color-primary);\n  color: var(--color-primary-content);\n  border-color: #244b71;\n}\n.btn-primary:hover { background: #244b71; }\n\n/* Кнопка БЕЗ РАМКИ (`btn-ghost`) — панель дій табличної частини й хрестик\n   видалення рядка. Там кнопок п'ять поспіль над щільною таблицею, і сірі\n   прямокутники читаються як ще одна рамка навколо порожнечі, а не як дії:\n   значення несе сама іконка, тож усе інше — шум.\n\n   Розмітка це вже казала (`btn-ghost` стоїть на кнопці рядка з самого початку),\n   але не діяла: `.btn` вище задає `background` і `border` БЕЗУМОВНО і поза\n   `@layer`, а `btn-ghost` daisyUI лежить у шарі компонентів — тобто тема гасила\n   його мовчки. Та сама пастка, що з `btn-square` нижче, тому й лікується так\n   само: селектор із двох класів, щоб виграти в самої `.btn`.\n\n   `border-color`, а не `border: 0`: рамка лишається на місці прозорою, і кнопка\n   не міняє розміру — інакше сусіди стрибали б. `:disabled` тут теж свій, бо\n   спільне правило вимкненого стану нижче малює сіру заливку, а вимкнена ghost\n   мусить лишитися невидимою (приглушену іконку дає його ж `color`). */\n.btn.btn-ghost,\n.btn.btn-ghost:disabled,\n.btn.btn-ghost[disabled] {\n  background-color: transparent;\n  border-color: transparent;\n}\n.btn.btn-ghost:hover { background-color: #e3eaf3; }\n.btn.btn-ghost:disabled:hover,\n.btn.btn-ghost[disabled]:hover { background-color: transparent; }\n\n/* Червоної кнопки-іконки тут НЕМАЄ навмисно, хоча `text-error` стоїть у розмітці\n   кількох таких кнопок (`ui-date`, `ui-image`, `ui-attachments`, редактори\n   шаблону й меню). `color` у `.btn` поза шарами його гасить, і одного разу це\n   вже виправляли правилом `.btn.text-error` — а екран одразу став рябим: у\n   табличній частині рядків двадцять, тобто двадцять червоних значків підряд, і\n   червоне переставало означати «обережно». Колір лишається за станом даних\n   (позначка на видалення, помилка поля), а не за кнопкою, яка просто прибирає\n   рядок. У табличній частині клас прибрано й з розмітки — щоб код не обіцяв\n   червоного, якого там свідомо немає; в решті компонентів він поки лежить як є\n   і нічого не робить. */\n\n/* Инпуты */\n.input, .select, .textarea {\n  font-size: var(--default-font-size);\n  height: 24px;\n  min-height: 24px;\n  padding-inline: 6px;\n  border-radius: var(--radius-field);\n  /* Колір рамки — через змінну, щоб її міг перебити предок (.field-invalid).\n     Саме змінною, а не селектором: контроли ui-kit живуть у власних shadow\n     root, куди селектор із форми не дістає, а успадкована CSS-змінна — так. */\n  border: 1px solid var(--field-border, var(--app-border-field));\n  /* Саме background-COLOR, а не скорочення `background`: скорочення мовчки\n     обнуляє background-image, а ним daisyUI малює стрілку в `.select` — поле\n     вибору ставало не відрізнити від звичайного інпута. */\n  background-color: var(--app-surface-strong);\n}\n\n/* Стрілка поля вибору. Малюнок daisyUI (два градієнти-трикутники) годиться,\n   а от його розкладка розрахована на власну висоту компонента: стрілка\n   стояла б за 20px від краю, а тексту не було б де закінчитись. Тут — під\n   контрол 24px: місце під стрілку в padding, сама вона біля правого краю. */\n.select {\n  padding-inline: 6px 18px;\n  background-image:\n    linear-gradient(45deg, transparent 50%, currentColor 50%),\n    linear-gradient(135deg, currentColor 50%, transparent 50%);\n  background-position: calc(100% - 13px) calc(50% - 1px), calc(100% - 9.1px) calc(50% - 1px);\n  background-size: 4px 4px, 4px 4px;\n  background-repeat: no-repeat;\n}\n.input:focus, .select:focus, .textarea:focus {\n  outline: 1px solid var(--color-primary);\n  border-color: var(--color-primary);\n}\n/* Коли input всередині join — outline на весь join, не на input */\n.join:focus-within {\n  outline: 1px solid var(--color-primary);\n  border-radius: var(--radius-field);\n}\n.join .input:focus,\n.join .input:focus-within {\n  outline: none;\n  border-color: var(--color-primary);\n}\n\n/* Невалідне поле форми. Клас ставить BaseUI.renderField() (і компоненти\n   ui-kit на себе, коли їм передали `invalid`); усередині достатньо перевизначити\n   змінну — рамку підхоплять і звичайний .input, і контрол у чужому shadow root. */\n.field-invalid {\n  --field-border: var(--color-error);\n  /* Точка відліку для плаваючого тексту помилки — див. .field-error нижче. */\n  position: relative;\n}\n/* Те саме для компонента з власним підписом (`<ui-picker invalid=\"...\">`):\n   тема адоптована в кожен shadow root, тому :host тут спрацьовує зсередини.\n   Порожнє значення = «помилки немає», а атрибут при цьому присутній.\n   Потрібне окремо від .field-invalid заради режиму комірки (`cell`), де\n   обгортки з класом немає взагалі. */\n:host([invalid]:not([invalid=\"\"])) { --field-border: var(--color-error); }\n\n/* Текст помилки НЕ бере участі в потоці навмисно. Інакше дві біди: поява й\n   зникнення помилки смикали б висоту всієї форми, а довге повідомлення у\n   вузькій колонці (`w-40` під ЄДРПОУ) розповзалося б на три-чотири рядки.\n   Плаваюча підказка натомість росте вбік до max-width і лише потім переносить\n   рядок — від ширини самого поля вона не залежить. */\n.field-error {\n  position: absolute;\n  top: 100%;\n  left: 0;\n  z-index: 30;\n  margin-top: 2px;\n  min-width: 100%;\n  width: max-content;\n  max-width: 18rem;\n  padding: 1px 6px;\n  font-size: var(--default-font-size);\n  line-height: 1.35;\n  color: var(--color-error);\n  background: var(--app-surface-strong);\n  border: 1px solid var(--color-error);\n  border-radius: var(--radius-field);\n}\n\n/* Плейсхолдер — тим самим токеном, що й решта другорядного тексту. Типовий\n   плейсхолдер браузера дає ~3.1:1; він несе підказку («Пошук…», «номер\n   підставиться»), тобто це текст, а не декор. `opacity: 1` обов'язковий —\n   Firefox інакше додає власну прозорість зверху. */\n.input::placeholder,\n.textarea::placeholder {\n  color: var(--app-text-muted);\n  opacity: 1;\n}\n\n/* Label */\n.label { padding: 1px 0; }\n.label-text { font-size: var(--default-font-size); color: var(--app-text-muted); }\n\n/* Зірочка обов'язковості. Один контракт на всі підписи — і `renderField()`\n   форми, і власні підписи компонентів (`ui-picker`, `ui-date`, `ui-decimal`,\n   `ui-select`, `ui-image`) ставлять той самий `<span class=\"field-required\">`.\n   Доти в кожному з десяти місць лежало `class=\"text-error ml-0.5\"`, тобто\n   вигляд позначки був розсипаний по розмітці й мінявся б у десяти місцях.\n\n   Зазор — 4px замість 8px. Вісім набігали з двох джерел: `.label` у daisyUI 5\n   це `inline-flex` із `gap: .375rem` (6px), і зверху ще `ml-0.5` (2px). На\n   вузькому контролі підпис із такою позначкою заходив на сусідній: `.label`\n   несе `white-space: nowrap`, тож зайве не переноситься, а вилазить.\n\n   Зазор задається `gap` самого підпису, а не маргіном зірочки: маргін довелося\n   б робити ВІД'ЄМНИМ, щоб перебити `gap` daisyUI, і величина мовчки поїхала б\n   услід за їхньою. Селектор звужений через `:has()` — `.label` носять і рядки\n   з прапорцем (`.label` + `gap-2` у розмітці), і їх чіпати не можна. */\n.label:has(> .field-required) { gap: 4px; }\n.field-required { color: var(--color-error); }\n\n/* Приглушений текст: коди, дати, підказки, порожні стани, лічильники.\n   Клас, а не прозорість. `text-base-content/50` дає на білому 2.82:1, `/40` —\n   2.22, `/60` — 3.67; тобто ВЕСЬ другорядний текст застосунку стояв нижче\n   порога AA, місцями вдвічі. Прозорістю це не лікується: щоб дотягнути до 4.5,\n   довелося б підняти її настільки, що «приглушеність» зникає — потрібен інший\n   колір, а не інша прозорість. */\n.text-muted { color: var(--app-text-muted); }\n/* Legacy: .form-control — клас daisyUI 4, у 5-й версії його немає. Лишився\n   тільки для редактора шаблонів друку; у формах моделей використовуй\n   BaseUI.renderField() — він дає ту саму розкладку, що ui-picker/ui-date. */\n.form-control { margin-bottom: 6px; }\n\n/* Таблицы — сетка как в 1С */\n.table {\n  font-size: var(--default-font-size);\n  border-collapse: collapse;\n  background: var(--app-surface-strong, #ffffff);\n}\n.table :not(thead, tfoot) tr {\n  font-size: var(--default-font-size);\n}\n.table th {\n  background: #e3eaf0;\n  color: #354a59;\n  font-weight: 500;\n  padding: 3px 8px;\n  border: 1px solid var(--app-border);\n  font-size: var(--default-font-size);\n}\n.table td {\n  padding: 3px 8px;\n  border: 1px solid #d9e0e6;\n  line-height: 1.4;\n}\n.table tr.hover:hover td,\n.table-zebra tbody tr:hover td {\n  background: #dcebf8;\n  cursor: pointer;\n}\n.table-zebra tbody tr:nth-child(even) td {\n  background: #fbfcfd;\n}\n\n/* Join — групування елементів в один блок */\n.join { display: flex; align-items: stretch; }\n.join .join-item {\n  border-radius: 0 !important;\n  margin-inline-start: -1px;\n}\n.join .join-item:first-child { border-radius: var(--radius-field) 0 0 var(--radius-field) !important; margin-inline-start: 0; }\n.join .join-item:last-child  { border-radius: 0 var(--radius-field) var(--radius-field) 0 !important; }\n.join .join-item:only-child  { border-radius: var(--radius-field) !important; margin-inline-start: 0; }\n.join .join-item:focus,\n.join .join-item:focus-within { position: relative; z-index: 1; }\n\n/* ── Вимкнений стан ───────────────────────────────────────────────────────\n   Свого правила для `:disabled` тут не було жодного, а `.btn` і `.input` вище\n   задають `background` та `color` БЕЗУМОВНО і поза `@layer` — тобто штатне\n   оформлення вимкненого контрола з daisyUI до нього не доходило взагалі. Та\n   сама пастка, що з `--border` і чекбоксами, тільки видима не одразу: кнопка\n   лишалася звичайною, і єдиною відмінністю було те, що вона не світлішає під\n   курсором. Найгірше це виглядало на «Провести» в новому документі — суцільна\n   синя кнопка, яка нічого не робить.\n\n   Сигналів свідомо кілька, і головний з них — НЕ заливка: різниця фонів\n   #e4e9ee проти #f5f7fa це 1.14:1, тобто самій по собі їй віри мало (рівно на\n   це й була скарга). Головне — стрибок кольору тексту з майже чорного\n   (11.44:1) у сірий (3.00:1) і втрата власного кольору в акцентних кнопок.\n   Перекриття спрацьовує без `!important`: `:disabled` рахується за клас, тож\n   `.btn:disabled` (0,2,0) сильніше за `.btn-primary` (0,1,0). */\n\n.btn:disabled,\n.btn[disabled],\n.btn-disabled {\n  background-color: #e4e9ee;\n  border-color: #cfd8df;\n  color: #78879a;              /* на заливці вимкненого: 3.00 */\n  cursor: not-allowed;\n}\n/* Не реагувати на курсор — інакше кнопка обіцяє дію, якої не буде. */\n.btn:disabled:hover,\n.btn[disabled]:hover,\n.btn-disabled:hover {\n  background-color: #e4e9ee;\n}\n\n/* Поле — інша річ, і різниця тут принципова. Підпис кнопки в цьому стані\n   читати не треба, а ЗНАЧЕННЯ поля — треба: у режимі перегляду форма вимкнена\n   цілком (`fieldset[disabled]`), і користувач прийшов саме читати. Тому текст\n   лишається вище порога AA (4.75), а «недоступність» несуть заливка й курсор.\n   Сіра заливка проти білого в редагованому полі — класична ознака саме тому,\n   що площа велика: там, де для тексту 1.15:1 було б катастрофою, для фону\n   цього достатньо. */\n.input:disabled,\n.select:disabled,\n.textarea:disabled {\n  background-color: #eceff2;\n  color: var(--app-text-muted);   /* на заливці вимкненого: 4.75 */\n  cursor: not-allowed;\n}\n/* Прапорці й перемикачі — графіка, не текст, тож тут прозорість доречна. */\n.checkbox:disabled,\n.radio:disabled,\n.toggle:disabled {\n  opacity: .5;\n  cursor: not-allowed;\n}\n\n/* ── Табличні частини документів ──────────────────────────\n   Контракт (перенесено з altera_danet, .app-table--tabular-section):\n   сітку малює ТІЛЬКИ таблиця, контрол у комірці не має власної рамки,\n   заокруглень, тіні й фону та займає комірку цілком.\n\n   Правила живуть тут, а не в компонентах, бо цей лист адоптується в кожен\n   shadow root (GlobalStyledLitElement) — отже дістає і до контролів усередині\n   ui-decimal / ui-picker.\n\n   ВАЖЛИВО: блок має йти ПІСЛЯ .input/.join/.table і теж поза @layer.\n   Утиліти Tailwind (шар utilities) тут не працюють — безшарові правила теми\n   перебивають будь-який шар незалежно від специфічності. */\n\n.table-tabular td {\n  padding: 0;\n  vertical-align: middle;\n}\n/* Текстові комірки (номер рядка, сума): горизонтальний відступ для читабельності,\n   вертикальний — нуль, інакше рядок стане вищим за контрол. */\n.table-tabular td.cell-text { padding: 0 8px; }\n\n.cell-control,\n.cell-control input,\n.cell-control .input,\n.cell-control .btn {\n  height: 24px;\n  min-height: 24px;\n  border: 0;\n  border-radius: 0 !important;\n  /* background-COLOR — з тієї ж причини, що й у `.input, .select`: скорочення\n     стерло б стрілку `.select` у комірці табличної частини. */\n  background-color: transparent;\n  box-shadow: none;\n}\n\n/* Контрол займає комірку по ширині (кнопки — фіксовані, див. нижче). */\n.cell-control,\n.cell-control input { width: 100%; }\n\n/* Власної рамки контрол у комірці не малює — межу веде сама таблиця. */\n.cell-control input:focus,\n.cell-control .input:focus,\n.cell-control .join-item:focus,\n.cell-control .join-item:focus-within {\n  outline: none;\n  border-color: transparent;\n}\n\n/* А ось САМА комірка фокус показує.\n   Раніше контур знімався й тут, і єдиним слідом фокуса лишалася підсвітка\n   РЯДКА (`tr.current`, #eef4fb) — це 1.11:1 до білого, тобто на межі\n   помітності. У текстовій комірці рятувала каретка й виділення тексту, а в\n   комірці-пікері не рятувало ніщо: не видно, де стоїш. Ціна цього вища за\n   звичайну: заповнення документа побудоване на клавіатурі (Enter, ↑↓, Insert),\n   тобто саме на сценарії, де курсора миші перед очима немає.\n   Контур усередину (`outline-offset: -1px`), як у `.cell-invalid`: власної\n   рамки в комірки немає, а зовнішній контур перекрив би сітку сусідів. */\n.cell-control:focus,\n.cell-control:focus-within {\n  outline: 1px solid var(--color-primary);\n  outline-offset: -1px;\n}\n\n/* Іконкові кнопки в комірці — рівно 24×24 без падінгів. */\n.cell-control .btn {\n  width: 24px;\n  min-width: 24px;\n  padding-inline: 0;\n}\n\n/* Командна панель форми редагування — угорі, над областю полів.\n   Ті самі фон і межа, що в тулбарі списку й шапці звіту: усі три — командна\n   смуга екрана, і читатися вони мусять однаково. */\n.form-actions {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 8px;\n  padding: 6px 8px;\n  background: var(--app-surface-strong, #ffffff);\n  border-bottom: 1px solid var(--app-border, #b8c3cc);\n}\n\n/* Роздільник груп у командній панелі — замість розпірки на всю ширину.\n   Розпірка відкидала другу групу до правого краю екрана, і кнопку доводилося\n   шукати очима: велика порожнеча читається не як «інша група», а як «тут нічого\n   немає». Тонка риска каже те саме на відстані 12 пікселів. */\n.toolbar-sep {\n  align-self: stretch;\n  width: 1px;\n  margin-inline: 4px;\n  background: var(--app-border, #b8c3cc);\n}\n\n/* Іконка в кнопці тулбара: трохи відсунута від підпису, вертикально по центру.\n   Розмір — з токена, і саме ЦЕ правило вирішує, а не атрибути `width`/`height`\n   на самому `<svg>`: у CSS звичайна декларація сильніша за презентаційний\n   атрибут завжди, незалежно від специфічності. Тому один рядок тут міняє\n   іконки в усіх кнопках застосунку — і в тих, що малює фреймворк, і в тих, що\n   екрани написали в себе.\n   Це не суперечить правилу «розмір атрибутами, не класами Tailwind»: там\n   ішлося про залежність від того, чи згенеровано `h-4` — тема ж їде в кожен\n   shadow root завжди, разом із рештою контрактів. */\n.btn > svg,\n.input > svg {\n  flex: 0 0 auto;\n  width: var(--icon-size);\n  height: var(--icon-size);\n}\n\n/* Кнопка-іконка (без підпису) — рівний квадрат під контрол 24px.\n   Задаємо тут, бо `btn-square` з daisyUI лежить у шарі компонентів, а `.btn`\n   цієї теми — поза шарами й перебиває його `padding`. Селектор із двох класів,\n   щоб виграти в самої `.btn`. Ім'я такій кнопці дає `aria-label`. */\n.btn.btn-square {\n  width: 24px;\n  min-width: 24px;\n  padding-inline: 0;\n}\n\n/* Загрузка */\n.loading { width: 16px; height: 16px; }\n\n/* ── Вкладки форми (кілька табличних частин) ──────────────────────────────\n   Розмітку малює `ui-kit/tabular/ui-form-tabs.ts`, вигляд — тут: кольори\n   мусять приходити токенами теми, а токен у розмітці означав би `style=\"…\"`\n   на кожній вкладці.\n\n   Активну вкладку позначає САМЕ ЛІНІЯ, а не лише шрифт: жирність на 14px\n   помітна тільки поруч із сусідом, тобто щойно відкрита вкладка від інших не\n   відрізнялася б. Лінія 2px кольором акценту читається з відстані й не зникає\n   в чорно-білому друку.\n\n   Щільність не піднімаємо (скіл screen-design-rules): висота вкладки — це\n   висота контрола, радіуси лишаються 2px, тіней немає. */\n.form-tabs {\n  display: flex;\n  align-items: flex-end;\n  gap: 2px;\n  border-bottom: 1px solid var(--app-border);\n}\n.form-tab {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  height: 26px;\n  padding-inline: 12px;\n  margin-bottom: -1px;              /* лінія вкладки лягає НА лінію смуги */\n  border: 0;\n  border-bottom: 2px solid transparent;\n  border-radius: 0;\n  background: transparent;\n  /* Кнопка, а не div (див. коментар у компоненті), тож шрифт доводиться\n     повернути явно — власний у неї від браузера. */\n  font: inherit;\n  color: var(--app-text-muted);\n  cursor: pointer;\n  white-space: nowrap;\n  user-select: none;\n}\n.form-tab:focus-visible {\n  outline: 2px solid var(--app-accent);\n  outline-offset: -2px;\n}\n.form-tab:hover {\n  color: var(--app-text);\n  border-bottom-color: var(--app-border-strong);\n}\n.form-tab[aria-selected=\"true\"] {\n  color: var(--app-text);\n  font-weight: 500;\n  border-bottom-color: var(--app-accent);\n}\n/* Панель під смугою: ЗАМКНЕНА рамка того ж кольору й зазор між нею та смугою.\n   Тримає таблицю з панеллю дій разом, щоб було видно: вони належать ВИБРАНІЙ\n   вкладці, а не формі взагалі.\n      Зазор саме ЗОВНІ рамки (`margin`), а не всередині (`padding`), і це не\n   те саме: панель без верхньої межі зливалася зі смугою в одну лінію, а\n   внутрішній відступ від цього не рятує — він відсуває таблицю НИЖЧЕ обводки,\n   тоді як розділити треба смугу й саму обводку. */\n.form-tab-panel {\n  margin-top: 6px;\n  border: 1px solid var(--app-border);\n  background: var(--app-surface-strong);\n  padding: 6px;\n}\n/* Зазор між панеллю дій і таблицею. Належить ТЕМІ, бо саме компонент вкладок\n   ставить ці два елементи підряд — доти зазор давала розмітка форми\n   (`<div class=\"… mb-1\">` навколо тулбара), і разом із переїздом панелі в\n   компонент він зник: над кнопками 6px, під ними 0, і рамка таблиці сходилася\n   зі смугою дій в одну лінію.\n      `margin`, а не `display: grid; gap`: величина та сама, але маргін не\n   складається з тим, що застосунок міг поставити собі сам як обхід, — а `gap`\n   склався б, і зазор став би подвійним. Селектор прямий (`>`) — форма з\n   власним `content` у вкладці має малювати свою розкладку сама. */\n.form-tab-panel > ui-tabular-toolbar { margin-bottom: 6px; }\n/* Лічильник рядків у вкладці. Порожня частина — приглушено: нуль не мусить\n   кричати, він мусить бути видним. */\n.form-tab-count {\n  font-size: 11px;\n  line-height: 1;\n  padding: 2px 5px;\n  border-radius: 8px;\n  background: var(--app-header);\n  color: var(--app-text-muted);\n}\n.form-tab[aria-selected=\"true\"] .form-tab-count {\n  background: var(--app-accent-soft);\n  color: var(--app-text);\n}\n/* Позначка «тут є помилка»: крапка кольором помилки. Кольором одним статус не\n   передається (скіл screen-design-rules), тому вкладка ще й несе `title`. */\n.form-tab-error { color: var(--color-error); font-weight: 700; }\n\n/* ── Діалоги застосунку ───────────────────────────────────────────────────\n   Спільний контракт модального вікна (confirm-host, вибір групи, будь-які\n   майбутні діалоги): «вікно 1С» — смуга заголовка кольору оболонки з\n   хрестиком, біле тіло, підвал дій на сірому. Живе в темі, бо лист\n   адоптується в кожен shadow root — діалог будь-якого компонента виглядає\n   однаково, без копіювання стилів. */\n.app-dialog-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 60;\n  display: grid;\n  place-items: center;\n  background: rgba(36, 55, 70, .45);\n}\n.app-dialog {\n  background: var(--color-base-100, #ffffff);\n  border: 1px solid var(--app-border-strong, #98a7b4);\n  border-radius: var(--radius-box, 2px);\n  box-shadow: 0 12px 40px rgba(0, 0, 0, .35);\n  min-width: 20rem;\n  max-width: 32rem;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n.app-dialog-title {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 5px 8px 5px 10px;\n  background: var(--color-primary, #2f5f8f);\n  color: var(--color-primary-content, #ffffff);\n  font-weight: 500;\n  user-select: none;\n}\n/* Хрестик — <button>, а не <span>: він закриває вікно, тобто це дія, і з\n   клавіатури до неї треба діставатися. Скидання нижче — щоб кнопка виглядала\n   так само, як виглядав span. */\n.app-dialog-close {\n  cursor: pointer;\n  opacity: .75;\n  font-size: 15px;\n  line-height: 1;\n  padding: 2px 5px;\n  border-radius: 2px;\n  background: none;\n  border: 0;\n  color: inherit;\n  font-family: inherit;\n}\n.app-dialog-close:hover { opacity: 1; background: rgba(255, 255, 255, .18); }\n.app-dialog-close:focus-visible {\n  opacity: 1;\n  outline: 1px solid var(--color-primary-content, #ffffff);\n  outline-offset: 1px;\n}\n.app-dialog-body { padding: 12px; }\n.app-dialog-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 8px 10px;\n  background: var(--app-header, #e7edf2);\n  border-top: 1px solid var(--app-border, #b8c3cc);\n}\n\n/* ─── Друк ────────────────────────────────────────────────────────────────\n   Правила рівня компонента: цей лист адоптується в кожен shadow root, тож\n   `.no-print`/`.print-only` працюють усередині форм. Розкладку документа й\n   оболонки задають інші два рівні — див. `client/ui-kit/report/print.ts`.\n\n   `.print-only` за замовчуванням схований — блок «назва звіту, організація,\n   період» потрібен лише на папері: на екрані те саме видно в тулбарі. */\n.print-only { display: none; }\n.print-title { font-size: 15px; font-weight: 700; margin: 0 0 2px; }\n.print-subtitle { font-size: 12px; color: #444; margin: 0; }\n\n/* ─── Графік у звіті ──────────────────────────────────────────────────────\n   Фреймворк графіків не малює — чим саме, вирішує застосунок. Але місце для\n   нього описане тут, бо з друком і експортом графік стикається однаково,\n   незалежно від бібліотеки.\n\n   Контракт: полотно чи SVG кладуть у `.report-chart`. Маркер потрібен саме\n   тому, що правила не можна повісити на `canvas, svg` взагалі — під `svg`\n   потрапили б і вбудовані іконки в комірках.\n\n   В Excel графік не потрапляє: аркуш читається з таблиці, а графік — не\n   таблиця. Якщо він усе-таки живе всередині `<table>` (рядок на всю ширину),\n   позначте цей рядок `no-export` — див. `client/ui-kit/report/table-model.ts`. */\n.report-chart { break-inside: avoid; }\n.report-chart canvas,\n.report-chart svg { max-width: 100%; height: auto; }\n\n@media print {\n  .no-print { display: none !important; }\n  .print-only { display: block !important; }\n\n  /* Фон шапки таблиці браузер за замовчуванням не друкує — без цього сітка\n     звіту на папері розсипається на однакові білі клітинки. */\n  .table th {\n    -webkit-print-color-adjust: exact;\n    print-color-adjust: exact;\n  }\n  .table th,\n  .table td {\n    padding: 2px 4px;\n    font-size: 9px;\n  }\n\n  /* Шапка повторюється на кожній сторінці (це стандартна поведінка thead,\n     але лише коли таблиця не всередині контейнера з прокруткою — його\n     розтискає рівень оболонки). Рядок не розривається між сторінками. */\n  thead { display: table-header-group; }\n  tfoot { display: table-footer-group; }\n  tr, td, th { break-inside: avoid; }\n\n  /* Посилання (рахунок, документ, субконто) на папері — звичайний текст:\n     підкреслення й колір там означають лише зайвий шум. */\n  .link, .btn.link, button.link {\n    color: inherit !important;\n    text-decoration: none !important;\n  }\n\n  /* Графік на папері. Три різні біди, і кожну лікує свій рядок:\n       · `break-inside` — інакше графік розсікається межею сторінки навпіл;\n       · `max-width` + `height: auto` — вписати в поля, зберігши пропорції.\n         Саме max-width, а не width: графік, вужчий за сторінку, не треба\n         розтягувати — від цього полотно тільки замилюється;\n       · `print-color-adjust` — браузер за замовчуванням не друкує заливки, і\n         стовпчикова діаграма виходить із самих контурів. Та сама причина, що\n         й у шапки таблиці вище. */\n  .report-chart {\n    break-inside: avoid;\n    page-break-inside: avoid;\n  }\n  .report-chart canvas,\n  .report-chart svg {\n    max-width: 100% !important;\n    height: auto !important;\n    -webkit-print-color-adjust: exact;\n    print-color-adjust: exact;\n  }\n}\n";
